typedef int SSEventId;
typedef unsigned int nslSoundId;
typedef unsigned int nslEmitterId;
#define NSL_INVALID_ID 0
#define NULL 0
enum { NSL_SOUNDSTATUS_INVALID = 0 };
extern "C" char *strcpy(char *, const char *);
extern "C" unsigned int strlen(const char *);
extern "C" int strnicmp(const char *, const char *, unsigned int) __asm__("strncasecmp");
extern int nslGetSoundStatus(nslSoundId);
extern void nslSetSoundEmitter(nslEmitterId, nslSoundId);
class stringx { public: const char *c_str() const; };
class entity { public: stringx get_parsed_name() const; };
class board_model;
class kellyslater_controller { public: board_model *get_my_board_model(); };
class world_dynamics_system { public: kellyslater_controller *get_ks_controller(int); };
extern world_dynamics_system *g_world_ptr;
enum EventType { SS_TUBER_TALK=50, SS_GENERIC_TALK=57, SS_WINDSURFER_TALK=61, SS_JETSKI_TALK=63, SS_KAYAK_TALK=65, SS_SPONGER_TALK=68, SS_RAFTER_TALK=70 };
class SoundScriptManager {
public:
  static SoundScriptManager *inst();
  SSEventId playEvent(EventType, entity *, float = 0);
  void endEvent(SSEventId, float = 0);
  nslSoundId getSoundId(SSEventId);
};
class os_developer_options {
public:
  enum flags_t { FLAG_NO_AUDIO };
  static os_developer_options *inst();
  bool is_flagged(flags_t) const;
};
struct WaveSound { char pad[0]; nslEmitterId behindTheCamera; };
extern WaveSound wSound;
class SFXEngine {
  char pad0[4468];
  bool paused;
public:
  void sprayed(entity *sprayed);
};

void SFXEngine::sprayed(entity *sprayed)
{
	SSEventId s=-1;
	nslSoundId snd=NSL_INVALID_ID;
  if (paused) return;
	if (os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_AUDIO))
		return;
  char entity_name[30];
  if ( sprayed )
  {
    strcpy( entity_name, sprayed->get_parsed_name( ).c_str( ) );

		if ( strnicmp( entity_name, "fatbastard", strlen( "fatbastard" ) )==0 )
		{
			s = SoundScriptManager::inst()->playEvent(SS_TUBER_TALK, NULL);
			SoundScriptManager::inst()->endEvent(s, 4);
		}
		else if ( strnicmp( entity_name, "boogieboarder", strlen( "boogieboarder" ) )==0 )
		{
			s=SoundScriptManager::inst()->playEvent(SS_SPONGER_TALK, NULL);
			SoundScriptManager::inst()->endEvent(s, 4);
		}
		else if (strnicmp( entity_name, "jetskier", strlen( "jetskier" ) )==0 )
		{
			s=SoundScriptManager::inst()->playEvent(SS_JETSKI_TALK, NULL);
			SoundScriptManager::inst()->endEvent(s, 4);
		}
		else if (strnicmp( entity_name, "dingy", strlen( "dingy" ) )==0 )
		{
			s=SoundScriptManager::inst()->playEvent(SS_RAFTER_TALK, NULL);
			SoundScriptManager::inst()->endEvent(s, 4);
		}
		else if (strnicmp( entity_name, "kayak", strlen( "kayak" ) )==0 )
		{
			s=SoundScriptManager::inst()->playEvent(SS_KAYAK_TALK, NULL);
			SoundScriptManager::inst()->endEvent(s, 4);
		}
		else if (strnicmp( entity_name, "wind_surfer", strlen( "wind_surfer" ) )==0 )
		{
			s=SoundScriptManager::inst()->playEvent(SS_WINDSURFER_TALK, g_world_ptr->get_ks_controller(0)->get_my_board_model());
			SoundScriptManager::inst()->endEvent(s, 4);
		}
		else
		{
			s=SoundScriptManager::inst()->playEvent(SS_GENERIC_TALK, NULL);
			SoundScriptManager::inst()->endEvent(s, 4);
		}

		if (s > -1)
		{
			snd =SoundScriptManager::inst()->getSoundId(s);
			if (nslGetSoundStatus(snd) != NSL_SOUNDSTATUS_INVALID)
			{
				nslSetSoundEmitter(wSound.behindTheCamera, snd);	
			}
		}
  }


}
